 const headers={Origin:origin},native=async(path,data,expected=data===undefined?200:201)=>{const r=await context.request.fetch(origin+'/api/operator'+path,{method:data===undefined?'GET':'POST',headers,...data===undefined?{}:{data}});assert.equal(r.status(),expected,await r.text());return r.json()}
 const dataset='synthetic-bifocal-rdl-render-rows'
 await upload(dataset,'invoice,region,customer,amount\n'+Array.from({length:70},(_,i)=>(i+1)+',West,A,1.01').join('\n')+'\n999,West,B,88888.88\n1000,East,A,98765.43\n')
