 const base={version:1,dataset,joins:[],filters:[],groupBy:['invoice','region','customer'],measures:[{id:'amount',op:'sum',column:'amount',unit:'number',scale:2}],context:{modelVersion:'synthetic-bifocal-rdl',metricVersion:'synthetic-bifocal-rdl',accountingBasis:'not-applicable',calendar:{id:calendar,version:1},rounding:'half-even'}}
 const detailQuery=await native('/queries/run',{...base,filters:[{column:'region',op:'eq',value:'West'}]}),regionQuery=await native('/queries/run',{...base,groupBy:['region']}),customerQuery=await native('/queries/run',{...base,groupBy:['region','customer']})
 const ns='http://schemas.microsoft.com/sqlserver/reporting/2016/01/reportdefinition',field=name=>`<Field Name="${name}"><DataField>${name}</DataField></Field>`,parameter=(name,lookup)=>`<ReportParameter Name="${name}"><DataType>String</DataType>${name==='Region'?'<DefaultValue><Values><Value>West</Value></Values></DefaultValue>':''}<ValidValues><DataSetReference><DataSetName>${lookup}</DataSetName><ValueField>${name}</ValueField></DataSetReference></ValidValues></ReportParameter>`
 const queryParameter=name=>`<QueryParameter Name="@${name}"><Value>=Parameters!${name}.Value</Value></QueryParameter>`
 const data=(name,fields,parameters=[])=>`<DataSet Name="${name}"><Query><CommandText>inert source query</CommandText><QueryParameters>${parameters.map(queryParameter).join('')}</QueryParameters></Query><Fields>${fields.map(field).join('')}</Fields></DataSet>`
 const box=(name,value,format='')=>`<Textbox Name="${name}"><Value>${value}</Value>${format?`<Style><Format>${format}</Format></Style>`:''}</Textbox>`
